import math

def check_divisibility(n):
    # The expression is 3((n+2)! + 1) / (2n - 1)

    denominator = 2 * n - 1

    # Check for zero denominator, though not expected for integer n in range(0, 13)
    if denominator == 0:
        return False # Or handle as appropriate, but 2n-1 = 0 iff n = 0.5

    # Calculate the numerator: 3 * ((n+2)! + 1)
    try:
        factorial_val = math.factorial(n + 2)
        numerator = 3 * (factorial_val + 1)
    except OverflowError:
        # Should not happen for n <= 12 (max factorial is 14!)
        print(f"Warning: Overflow encountered for n={n}")
        return False

    # Check divisibility
    if numerator % denominator == 0:
        return True
    else:
        return False

results = {}
for n in range(13):
    is_integer = check_divisibility(n)
    results[n] = is_integer

print("Values of n (0 to 12) for which the expression is an integer:")
for n, result in results.items():
    print(f"n = {n}: {result}")

