import math

def is_solution(n):
    if n < 0:
        return False

    # Denominator
    d = 2 * n - 1

    # Handle the case d=0 if n=0.5, but we only check integer n >= 0.
    # If n=0, d=-1. If n=0, 3*((2)!+1) / -1 = -9/1 = -9 (Integer).
    if d == 0:
        return False # Should not happen for integer n >= 0

    # Numerator term
    # We need to check if 3 * ((n+2)! + 1) is divisible by d.
    try:
        fact = math.factorial(n + 2)
    except OverflowError:
        # For n=50, n+2=52. 52! is very large but standard Python integers handle it.
        # This is a safeguard, but probably unnecessary.
        return False 

    numerator = 3 * (fact + 1)

    if numerator % d == 0:
        return True
    else:
        return False

# List of candidate n values (n <= 50 such that 2n-1 is prime or n in {0, 1, 2})
candidates = [
    0, 1, 2, 3, 4, 6, 7, 9, 10, 12, 15, 16, 19, 21, 22, 24, 
    27, 30, 31, 34, 36, 37, 40, 42, 45, 49
]

solutions = []
for n in candidates:
    if is_solution(n):
        solutions.append(n)

print(f"Solutions found up to n=50 among the filtered candidates: {solutions}")

